import{_ as t,m as d,k as o,ah as a}from"./chunks/framework.HEc25T99.js";const p=JSON.parse('{"title":"Utilitaires","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"fr/developers/development/utilities.md","filePath":"src/fr/developers/development/utilities.md"}'),r={name:"fr/developers/development/utilities.md"};function c(s,e,n,i,l,u){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="utilitaires" tabindex="-1">Utilitaires <a class="header-anchor" href="#utilitaires" aria-label="Permalink to &quot;Utilitaires&quot;">​</a></h1><p>En complément des <a href="./sections-widgets.html">sections et widgets</a> et des <a href="./content-models.html">modèles de contenu</a>, Creopse expose deux niveaux d&#39;API consommables depuis un composant : des <strong>composables</strong> (Vue) / <strong>hooks</strong> (React) qui donnent accès aux données de la plateforme (<code>@creopse/vue</code>/<code>@creopse/react</code>), et des <strong>fonctions utilitaires pures</strong> partagées par les deux stacks (<code>@creopse/utils</code>).</p><div class="tip custom-block"><p class="custom-block-title">Vue vs React</p><p>Les composables/hooks portent le même nom et la même signature sur les deux stacks — seule la syntaxe change. Côté Vue, <code>const { tr } = useHelper()</code> retourne des valeurs directement exploitables dans le template (pas de <code>.value</code> à gérer pour les fonctions, uniquement pour les quelques <code>Ref</code> documentées ci-dessous). Côté React, tout est exploitable tel quel, sans déréférencement. Tout ce qui vient de <code>@creopse/utils</code> (<code>formatDate</code>, <code>hexToRgba</code>...) est strictement identique dans les deux stacks.</p></div><h2 id="composables-hooks-disponibles" tabindex="-1">Composables / hooks disponibles <a class="header-anchor" href="#composables-hooks-disponibles" aria-label="Permalink to &quot;Composables / hooks disponibles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Composable / Hook</th><th>Rôle</th></tr></thead><tbody><tr><td><code>useHelper()</code></td><td>Fonctions transverses : traduction, résolution de fichiers/liens, responsive, langue active.</td></tr><tr><td><code>useContent()</code></td><td>Données de page, sections, modèles de contenu, informations de base.</td></tr><tr><td><code>useMenu()</code></td><td>Lecture des menus et de leurs items, résolution de liens.</td></tr><tr><td><code>useNews()</code></td><td>Articles, catégories, tags et commentaires (actualités).</td></tr><tr><td><code>useVideo()</code></td><td>Catégories et items vidéo.</td></tr><tr><td><code>useNewsletter()</code></td><td>Abonnement newsletter par email ou téléphone.</td></tr><tr><td><code>useApi()</code></td><td>Requêtes HTTP génériques vers l&#39;API.</td></tr><tr><td><code>useProps()</code></td><td>Props réactives de la page courante (Inertia).</td></tr><tr><td><code>useConfig()</code></td><td>Configuration du plugin (URL de base, locale...).</td></tr></tbody></table><h2 id="usehelper" tabindex="-1"><code>useHelper()</code> <a class="header-anchor" href="#usehelper" aria-label="Permalink to &quot;`useHelper()`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Membre</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>tr</code></td><td><code>(data, lang?) =&gt; string</code></td><td>Traduit un champ <code>i18n-text</code>.</td></tr><tr><td><code>rHtml</code></td><td><code>(data, lang?) =&gt; string</code></td><td>Traduit et résout un champ <code>i18n-editor</code> (toujours via <code>v-html</code>/<code>dangerouslySetInnerHTML</code>).</td></tr><tr><td><code>fileUrl</code></td><td><code>(path) =&gt; string</code></td><td>URL absolue d&#39;un fichier (<code>storage/&lt;path&gt;</code>).</td></tr><tr><td><code>getImage</code></td><td><code>(path, size?) =&gt; Promise&lt;string&gt;</code></td><td>URL de la miniature demandée (<code>small</code>/<code>medium</code>/<code>large</code>/<code>original</code>), repli sur l&#39;original si absente.</td></tr><tr><td><code>getVideoThumbnail</code></td><td><code>(path) =&gt; string</code></td><td>URL de la miniature d&#39;une vidéo.</td></tr><tr><td><code>resolveUrl</code></td><td><code>(path) =&gt; string</code></td><td>Résout une URL relative vers l&#39;URL de base de l&#39;API.</td></tr><tr><td><code>openLink</code></td><td><code>(entity) =&gt; void</code></td><td>Ouvre un lien (id de menu, URL brute, ou route Inertia) — voir <a href="./sections-widgets.html#liens-et-boutons-cta">Liens et boutons CTA</a>.</td></tr><tr><td><code>languages</code></td><td><code>Language[]</code></td><td>Langues disponibles (<code>fr</code>, <code>en</code>).</td></tr><tr><td><code>updateLang</code></td><td><code>(val, reload?, updateUserPrefs?) =&gt; Promise&lt;void&gt;</code></td><td>Change la langue active.</td></tr><tr><td><code>socialNetworks</code></td><td><code>{ name; icon }[]</code></td><td>Liste des réseaux sociaux supportés (boucle Header/Footer).</td></tr><tr><td><code>detectSocialNetwork</code></td><td><code>(url) =&gt; { name; icon } | null</code></td><td>Détecte le réseau social d&#39;une URL.</td></tr><tr><td><code>isXlScreen</code> / <code>isLgScreen</code> / <code>isMdScreen</code> / <code>isSmScreen</code> / <code>is2XlScreen</code></td><td><code>Ref&lt;boolean&gt;</code> (Vue)</td><td>Points de rupture responsive courants.</td></tr><tr><td><code>currentRoutePath</code></td><td><code>Ref&lt;string&gt;</code> (Vue)</td><td>Chemin de la page Inertia courante.</td></tr><tr><td><code>displayFormErrors</code></td><td><code>(errors, displayError) =&gt; void</code></td><td>Affiche les erreurs de formulaire via un callback.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>getActiveLanguage()</code> (utilisé pour la valeur courante d&#39;un sélecteur de langue) n&#39;est <strong>pas</strong> fourni par <code>useHelper()</code> — c&#39;est une fonction auto-importée de <code>laravel-vue-i18n</code> côté Vue.</p></div><h2 id="usecontent" tabindex="-1"><code>useContent()</code> <a class="header-anchor" href="#usecontent" aria-label="Permalink to &quot;`useContent()`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Membre</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>getSectionRootData</code></td><td><code>(key?) =&gt; any</code></td><td>Champs singletons d&#39;une section (équivalent de <code>getSectionData(key)?.index</code>).</td></tr><tr><td><code>getSectionData</code></td><td><code>(key?) =&gt; any</code></td><td>Données complètes d&#39;une section (singletons + collections).</td></tr><tr><td><code>getSectionSettings</code></td><td><code>(key?) =&gt; any</code></td><td>Réglages d&#39;affichage d&#39;une section.</td></tr><tr><td><code>getSectionSettingsGroup</code> / <code>getSectionSetting</code></td><td><code>(key?, group, name?) =&gt; any</code></td><td>Groupe ou réglage précis.</td></tr><tr><td><code>getAnySectionData</code></td><td><code>(sectionSlug, pageSlug, linkId?) =&gt; Promise&lt;any&gt;</code></td><td>Données d&#39;une section depuis n&#39;importe quelle page.</td></tr><tr><td><code>getContentModel</code></td><td><code>(name) =&gt; ContentModelModel | undefined</code></td><td>Modèle de contenu par nom.</td></tr><tr><td><code>getContentModelItems</code></td><td><code>(name, activeOnly?) =&gt; Promise&lt;ContentModelItemModel[]&gt;</code></td><td>Items d&#39;un modèle de contenu — voir <a href="./content-models.html">Modèles de contenu</a>.</td></tr><tr><td><code>getPaginatedContentModelItems</code></td><td><code>(name, page, pageSize, activeOnly?, query?, dataFilters?, sortBy?, sortDirection?) =&gt; Promise&lt;PaginatedContentModelItems&gt;</code></td><td>Items paginés, avec filtres.</td></tr><tr><td><code>submitUserContentModelItem</code></td><td><code>(title, contentModelId, singletonsData?, collectionsData?, onSuccess?, onError?) =&gt; Promise&lt;Response&gt;</code></td><td>Soumet un item utilisateur (formulaires).</td></tr><tr><td><code>getContentPath</code></td><td><code>(item, force?) =&gt; string</code></td><td>Chemin permalien d&#39;un item ou d&#39;un article.</td></tr><tr><td><code>getAppInformationValue</code></td><td><code>(key, type?) =&gt; any</code></td><td>Valeur d&#39;une information de base (voir tableau ci-dessous).</td></tr><tr><td><code>pageData</code></td><td><code>PageModel | null</code></td><td>Données de la page courante.</td></tr><tr><td><code>contentModelItem</code></td><td><code>ContentModelItemModel | null</code></td><td>Item de modèle de contenu courant (page de détail).</td></tr><tr><td><code>newsArticle</code> / <code>newsCategory</code> / <code>newsTag</code></td><td>—</td><td>Article/catégorie/tag de news courant.</td></tr><tr><td><code>appPrimaryColor</code> / <code>appSecondaryColor</code> / <code>appAccentColor</code></td><td><code>string</code></td><td>Couleurs de marque configurées.</td></tr><tr><td><code>logo</code> / <code>icon</code></td><td><code>string</code></td><td>URL du logo / de l&#39;icône configurés.</td></tr></tbody></table><h3 id="cles-getappinformationvalue" tabindex="-1">Clés <code>getAppInformationValue</code> <a class="header-anchor" href="#cles-getappinformationvalue" aria-label="Permalink to &quot;Clés `getAppInformationValue`&quot;">​</a></h3><p>Ne jamais recréer un champ de section pour l&#39;une de ces valeurs — les consommer directement via <code>getAppInformationValue(&#39;&lt;clé&gt;&#39;)</code> :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name, icon, oneColorIcon, logo, oneColorLogo, phone, email, address, postalCode,</span></span>\n<span class="line"><span>description, primaryColor, secondaryColor, accentColor, facebook, twitter, instagram,</span></span>\n<span class="line"><span>whatsapp, linkedin, youtube, pinterest, snapchat, tiktok, telegram, discord, reddit,</span></span>\n<span class="line"><span>tumblr, vimeo, twitch, github, dribbble, behance, medium, stackOverflow, threads,</span></span>\n<span class="line"><span>messenger, playstore, appstore, additionalInfo</span></span></code></pre></div><p>Ces valeurs sont gérées via <a href="./../resources/cli.html#creopse-base-info-alias-info"><code>creopse base-info</code></a>.</p><h2 id="usemenu" tabindex="-1"><code>useMenu()</code> <a class="header-anchor" href="#usemenu" aria-label="Permalink to &quot;`useMenu()`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Membre</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>getMenu</code></td><td><code>(name, activeOnly?, nested?) =&gt; MenuModel | undefined</code></td><td>Menu par nom.</td></tr><tr><td><code>getMenuByLocation</code></td><td><code>(name, activeOnly?, nested?) =&gt; MenuModel | undefined</code></td><td>Menu par location.</td></tr><tr><td><code>getMenuItems</code></td><td><code>(name, visibleOnly?, nested?) =&gt; MenuItemModel[]</code></td><td>Items d&#39;un menu par nom.</td></tr><tr><td><code>getMenuItemsByLocation</code></td><td><code>(name, visibleOnly?, nested?) =&gt; MenuItemModel[]</code></td><td>Items par location — le plus utilisé pour un Header/Footer.</td></tr><tr><td><code>getMenuItemById</code></td><td><code>(id) =&gt; MenuItemModel | undefined</code></td><td>Item par id.</td></tr><tr><td><code>getMenuGroups</code> / <code>getMenuItemsByGroup</code> / <code>getMenuGroupedItems</code> / <code>getMenuUngroupedItems</code></td><td>—</td><td>Regroupement d&#39;items (dropdowns).</td></tr><tr><td><code>getMenuHref</code></td><td><code>(item) =&gt; string</code></td><td><code>href</code> résolu d&#39;un item de menu.</td></tr><tr><td><code>openMenu</code></td><td><code>(item?) =&gt; void</code></td><td>Navigue vers un item de menu selon son <code>targetType</code>.</td></tr><tr><td><code>getLinkFromMenuItemId</code></td><td><code>(id) =&gt; string</code></td><td>Lien résolu depuis un champ <code>menu-item-link</code>.</td></tr></tbody></table><p>Voir le pattern de rendu complet dans <a href="./sections-widgets.html#liens-et-boutons-cta">Liens et boutons CTA</a>.</p><h2 id="usenews" tabindex="-1"><code>useNews()</code> <a class="header-anchor" href="#usenews" aria-label="Permalink to &quot;`useNews()`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Membre</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>isLoading</code></td><td><code>Ref&lt;boolean&gt;</code></td><td>État de chargement.</td></tr><tr><td><code>loadArticles</code></td><td><code>(params: { pageSize, page?, query?, status?, categories?, tags?, months? }) =&gt; Promise&lt;{ articles; meta }&gt;</code></td><td>Articles paginés.</td></tr><tr><td><code>loadCategories</code> / <code>loadTags</code></td><td><code>(filterByIsVisible?) =&gt; Promise&lt;[]&gt;</code></td><td>Catégories/tags visibles.</td></tr><tr><td><code>loadArticlesMonths</code></td><td><code>() =&gt; Promise&lt;string[]&gt;</code></td><td>Mois disposant d&#39;articles (archives).</td></tr><tr><td><code>loadArticlesCount</code> / <code>loadArticlesCountByStatus</code> / <code>loadArticlesCountByAuthor</code></td><td>—</td><td>Compteurs d&#39;articles.</td></tr><tr><td><code>loadComments</code></td><td><code>(params: { pageSize, page?, query? }) =&gt; Promise&lt;{ comments; meta }&gt;</code></td><td>Commentaires paginés.</td></tr><tr><td><code>addComment</code></td><td><code>(comment, onSuccess?, onError?) =&gt; Promise&lt;Response&gt;</code></td><td>Ajoute un commentaire.</td></tr></tbody></table><p>Toujours passer par ce composable pour une liste d&#39;articles — jamais une collection de section, voir <a href="./sections-widgets.html">Sections &amp; Widgets</a>.</p><h2 id="usevideo" tabindex="-1"><code>useVideo()</code> <a class="header-anchor" href="#usevideo" aria-label="Permalink to &quot;`useVideo()`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Membre</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>isLoading</code></td><td><code>Ref&lt;boolean&gt;</code></td><td>État de chargement.</td></tr><tr><td><code>loadCategories</code></td><td><code>(filterByIsVisible?) =&gt; Promise&lt;VideoCategoryModel[]&gt;</code></td><td>Catégories vidéo.</td></tr><tr><td><code>loadVideoItems</code></td><td><code>(params) =&gt; Promise&lt;PaginatedVideoItems&gt;</code></td><td>Vidéos paginées.</td></tr></tbody></table><h2 id="usenewsletter" tabindex="-1"><code>useNewsletter()</code> <a class="header-anchor" href="#usenewsletter" aria-label="Permalink to &quot;`useNewsletter()`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Membre</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>isLoading</code></td><td><code>Ref&lt;boolean&gt;</code></td><td>État de chargement.</td></tr><tr><td><code>subscribeEmail</code></td><td><code>(email, onSuccess?, onError?) =&gt; Promise&lt;void&gt;</code></td><td>Abonne un email.</td></tr><tr><td><code>subscribePhone</code></td><td><code>(phone, onSuccess?, onError?) =&gt; Promise&lt;void&gt;</code></td><td>Abonne un numéro (espaces supprimés).</td></tr></tbody></table><p>Pattern d&#39;usage typique dans un Footer : voir <a href="./sections-widgets.html">Sections &amp; Widgets</a>.</p><h2 id="useapi-useprops-useconfig" tabindex="-1"><code>useApi()</code>, <code>useProps()</code>, <code>useConfig()</code> <a class="header-anchor" href="#useapi-useprops-useconfig" aria-label="Permalink to &quot;`useApi()`, `useProps()`, `useConfig()`&quot;">​</a></h2><ul><li><strong><code>useApi()</code></strong> — méthodes bas niveau (<code>request</code>, <code>getItemRequest</code>, <code>postItemRequest</code>, <code>putItemRequest</code>, <code>deleteItemRequest</code>, <code>getAllItemsRequest</code>, <code>handleError</code>) pour des appels HTTP hors du périmètre des composables métier ci-dessus.</li><li><strong><code>useProps()</code></strong> — retourne les props réactives de la page (données Inertia). Utilisé pour accéder à <code>contentModelItem</code>/<code>article</code> sur une page de détail, voir <a href="./content-models.html#consommer-un-modele-de-contenu">Modèles de contenu</a>.</li><li><strong><code>useConfig()</code></strong> — retourne la configuration du plugin (<code>apiBaseUrl</code>, <code>apiUrl</code>, <code>locale</code>, <code>fallbackLocale</code>, <code>debug</code>...).</li></ul><h2 id="composants-utilitaires" tabindex="-1">Composants utilitaires <a class="header-anchor" href="#composants-utilitaires" aria-label="Permalink to &quot;Composants utilitaires&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Besoin</th><th>Vue</th><th>React</th></tr></thead><tbody><tr><td>Image avec sélection de miniature</td><td><code>&lt;Image :src=&quot;...&quot; size=&quot;large&quot; /&gt;</code></td><td><code>&lt;Image src={...} size=&quot;large&quot; /&gt;</code></td></tr><tr><td>Image résolue par une promesse</td><td><code>&lt;AsyncImg :load=&quot;...&quot; /&gt;</code></td><td><code>&lt;AsyncImg load={...} /&gt;</code></td></tr><tr><td>Portail/modal (pas d&#39;équivalent JSX à <code>&lt;Teleport&gt;</code>)</td><td><code>&lt;Teleport to=&quot;body&quot;&gt;</code> (natif Vue)</td><td><code>&lt;MountedTeleport to=&quot;body&quot;&gt;</code></td></tr><tr><td>Transition/animation</td><td><code>&lt;Transition name=&quot;...&quot;&gt;</code> (natif Vue)</td><td><code>&lt;CustomTransition name=&quot;fade|slide-fade|bounce&quot;&gt;</code></td></tr><tr><td>Icône SVG d&#39;un champ <code>icon</code> (donnée en base)</td><td><code>&lt;ContentIcon :data=&quot;...&quot; :size=&quot;42&quot; /&gt;</code></td><td><code>&lt;ContentIcon data={...} size={42} /&gt;</code> (<code>@arkn/react-icon-picker</code>)</td></tr><tr><td>Icône statique (MDI, Bootstrap Icons...)</td><td><code>&lt;Icon icon=&quot;mdi:...&quot; /&gt;</code></td><td><code>&lt;Icon icon=&quot;mdi:...&quot; /&gt;</code> (<code>@iconify/react</code>)</td></tr><tr><td>Barre collante</td><td><code>&lt;StickyTop&gt;</code> / <code>&lt;StickyBottom&gt;</code></td><td><code>&lt;StickyTop&gt;</code> / <code>&lt;StickyBottom&gt;</code></td></tr><tr><td>Troncature de texte avec « lire plus »</td><td><code>&lt;ReadMore :text=&quot;...&quot; /&gt;</code></td><td><code>&lt;ReadMore text={...} /&gt;</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Côté React, chaque composant utilisé dans le JSX doit être <strong>explicitement importé</strong> en tête de fichier (<code>Image</code> depuis <code>@creopse/react</code>, <code>Icon</code> depuis <code>@iconify/react</code>...) — contrairement aux exemples Vue où certains composants Creopse sont enregistrés globalement par le plugin.</p></div><h2 id="fonctions-utilitaires-pures-creopse-utils" tabindex="-1">Fonctions utilitaires pures (<code>@creopse/utils</code>) <a class="header-anchor" href="#fonctions-utilitaires-pures-creopse-utils" aria-label="Permalink to &quot;Fonctions utilitaires pures (`@creopse/utils`)&quot;">​</a></h2><p>Communes aux deux stacks, importables depuis <code>@creopse/utils</code> ou <code>@creopse/utils/helpers</code>.</p><h3 id="dates" tabindex="-1">Dates <a class="header-anchor" href="#dates" aria-label="Permalink to &quot;Dates&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fonction</th><th>Description</th></tr></thead><tbody><tr><td><code>formatDate(date, { outPattern?, locale? })</code></td><td>Formate une date — <strong>le helper à utiliser pour tout affichage de date dans une section</strong>, plutôt qu&#39;un <code>toLocaleDateString</code> local.</td></tr><tr><td><code>reformatDate(date, { inPattern?, outPattern?, locale? })</code></td><td>Convertit une date d&#39;un format à un autre.</td></tr><tr><td><code>differenceFromNow(date, { locale?, pattern? })</code></td><td>Différence relative (« il y a 3 jours »).</td></tr><tr><td><code>differenceWithToday(date, { pattern?, unit? })</code></td><td>Différence entre une date et aujourd&#39;hui.</td></tr><tr><td><code>differenceBetweenDates(start, end, options?)</code></td><td>Différence entre deux dates.</td></tr><tr><td><code>getDateFromTimestamp(date, options?)</code></td><td>Formate un timestamp UNIX (secondes) en date.</td></tr><tr><td><code>getCurrentTimestamp()</code></td><td>Timestamp UNIX courant.</td></tr></tbody></table><h3 id="couleurs" tabindex="-1">Couleurs <a class="header-anchor" href="#couleurs" aria-label="Permalink to &quot;Couleurs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fonction</th><th>Description</th></tr></thead><tbody><tr><td><code>hexToRgba(hex, alpha)</code></td><td>Convertit un hexadécimal en <code>rgba(...)</code> — renvoie directement la chaîne complète, pas des composantes séparées.</td></tr><tr><td><code>genRandomColor()</code></td><td>Génère un hexadécimal aléatoire.</td></tr></tbody></table><h3 id="chaines-de-caracteres" tabindex="-1">Chaînes de caractères <a class="header-anchor" href="#chaines-de-caracteres" aria-label="Permalink to &quot;Chaînes de caractères&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fonction</th><th>Description</th></tr></thead><tbody><tr><td><code>capitalizeFirstLetter(string)</code></td><td>Met en majuscule la première lettre.</td></tr><tr><td><code>getNameInitials(name)</code></td><td>Initiales (2 lettres) d&#39;un nom composé.</td></tr><tr><td><code>extractNumber(string, options?)</code></td><td>Extrait un ou plusieurs nombres d&#39;une chaîne.</td></tr><tr><td><code>isTitleLike(value, options?)</code> / <code>extractTitleLike(data, tr, defaultValue?)</code></td><td>Détection heuristique de champ « titre ».</td></tr><tr><td><code>replaceStringParts(str, replacements)</code></td><td>Remplace plusieurs parties d&#39;une chaîne selon un dictionnaire.</td></tr></tbody></table><h3 id="nombres-et-tableaux" tabindex="-1">Nombres et tableaux <a class="header-anchor" href="#nombres-et-tableaux" aria-label="Permalink to &quot;Nombres et tableaux&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fonction</th><th>Description</th></tr></thead><tbody><tr><td><code>getRandomInteger(min, max)</code></td><td>Entier aléatoire inclusif.</td></tr><tr><td><code>abbreviateNumber(number)</code></td><td>Abrège un nombre (<code>1.2k</code>, <code>3.4M</code>...).</td></tr><tr><td><code>removeDuplicates(arr, property)</code></td><td>Déduplique un tableau selon une propriété.</td></tr><tr><td><code>shuffleArray(array)</code></td><td>Mélange un tableau (Fisher-Yates).</td></tr></tbody></table><h3 id="fichiers-images-et-urls" tabindex="-1">Fichiers, images et URLs <a class="header-anchor" href="#fichiers-images-et-urls" aria-label="Permalink to &quot;Fichiers, images et URLs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fonction</th><th>Description</th></tr></thead><tbody><tr><td><code>humanFileSize(bytes, si?, dp?)</code></td><td>Taille de fichier lisible.</td></tr><tr><td><code>getFileExtension(path)</code></td><td>Extension d&#39;un chemin de fichier.</td></tr><tr><td><code>compressImage(file, options?)</code></td><td>Compresse une image côté client.</td></tr><tr><td><code>isExternal(path)</code></td><td>Vrai si le chemin est une URL externe, un <code>mailto:</code> ou un <code>tel:</code>.</td></tr><tr><td><code>isURL(str)</code></td><td>Valide qu&#39;une chaîne est une URL.</td></tr><tr><td><code>removeTrailingSlash</code> / <code>removeLeadingSlash</code></td><td>Nettoyage de chemin.</td></tr></tbody></table><h3 id="divers" tabindex="-1">Divers <a class="header-anchor" href="#divers" aria-label="Permalink to &quot;Divers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fonction</th><th>Description</th></tr></thead><tbody><tr><td><code>sleep(ms)</code></td><td>Attend le nombre de millisecondes donné.</td></tr><tr><td><code>formatTimeFromSeconds(duration, options?)</code></td><td>Formate une durée en <code>HH:MM:SS</code>.</td></tr><tr><td><code>slideToId(id)</code></td><td>Défilement en douceur vers un élément.</td></tr><tr><td><code>getDistanceFromLatLonInKm(lat1, lon1, lat2, lon2)</code></td><td>Distance entre deux coordonnées (Haversine).</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Cette liste couvre les fonctions les plus utiles à la construction de sections. <code>@creopse/utils</code> expose également des enums, modèles de domaine et types partagés (<code>ContentModelItemModel</code>, <code>MenuItemModel</code>, <code>AppInformationKey</code>...) consommés en interne par les composables ci-dessus.</p></div>',45)])])}const g=t(r,[["render",c]]);export{p as __pageData,g as default};
